use vstd::prelude::*;

verus! {

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        n > 0,
        n < list.len(),
    ensures
        // Length is preserved.
        new_list.len() == list.len(),
        // Element-wise, this is a rotation: suffix starting at n, then prefix up to n.
        forall|i: int|
            0 <= i && i < list.len()
            ==> new_list[i]
                == (if i < (list.len() - n) as int {
                        list[(i + n as int) as int]
                    } else {
                        list[(i - (list.len() - n) as int) as int]
                    }),
{
    let len = list.len();
    debug_assert!(len > 0);
    debug_assert!(n > 0 && n < len);

    let mut new_list = Vec::with_capacity(len);
    new_list.extend_from_slice(&list[n..]);
    new_list.extend_from_slice(&list[..n]);
    new_list
}

} // verus!